from pathlib import Path

path = Path('convex/evidenceImpact.ts')
text = path.read_text(encoding='utf-8')

# Add scope helper import.
anchor = 'import type { Id } from "./_generated/dataModel";\n'
addition = anchor + 'import { evidenceGateRootKind, impactedWorkKindsForEvidence } from "./evidenceImpactScopeLogic";\n'
if addition not in text:
    if anchor not in text:
        raise SystemExit('import anchor missing')
    text = text.replace(anchor, addition, 1)

# Add removal-block helper after gate release helper.
anchor = '''function evidenceGateRelease(input: { action: "uploaded" | "removed"; evidenceKind?: string }, item: { kind: string; status: string }) {\n'''
if anchor not in text:
    raise SystemExit('gate release anchor missing')
# Insert helper after the complete evidenceGateRelease function by locating its return-null tail.
tail = '''  return null;\n}\n\nexport async function applyInventorEvidenceChange'''
helper = '''  return null;\n}\n\nfunction removedEvidenceGateBlock(evidenceKind: string | undefined) {\n  if (evidenceKind === "prototype_test") {\n    return {\n      blockedReason: "Current physical prototype test evidence is required before downstream prototype conclusions can be relied on.",\n      humanGateType: "physical_work" as const,\n      summary: "InventSmith blocked the physical prototype-evidence gate because its supporting evidence was removed.",\n    };\n  }\n  if (evidenceKind === "manufacturer_quote") {\n    return {\n      blockedReason: "A current real manufacturer quote/RFQ response is required before quote comparison and manufacturing readiness can proceed.",\n      humanGateType: "authorization" as const,\n      summary: "InventSmith blocked the manufacturer quote-evidence gate because its supporting quote/RFQ evidence was removed.",\n    };\n  }\n  if (evidenceKind === "sales_evidence") {\n    return {\n      blockedReason: "Current actual launch/sales/customer evidence is required before post-launch performance conclusions can proceed.",\n      humanGateType: "private_information" as const,\n      summary: "InventSmith blocked the launch evidence gate because its supporting actual-market evidence was removed.",\n    };\n  }\n  return null;\n}\n\nexport async function applyInventorEvidenceChange'''
if helper not in text:
    if tail not in text:
        raise SystemExit('gate helper insertion anchor missing')
    text = text.replace(tail, helper, 1)

# Add scoped graph calculation after work-item load.
old = '''  const workItems = await ctx.db\n    .query("atlasWorkItems")\n    .withIndex("by_inventionId", (q) => q.eq("inventionId", inventionId))\n    .collect();\n\n  for (const item of workItems) {'''
new = '''  const workItems = await ctx.db\n    .query("atlasWorkItems")\n    .withIndex("by_inventionId", (q) => q.eq("inventionId", inventionId))\n    .collect();\n  const impactedKinds = impactedWorkKindsForEvidence(workItems, input.evidenceKind);\n  const gateRootKind = evidenceGateRootKind(input.evidenceKind);\n\n  for (const item of workItems) {'''
if new not in text:
    if old not in text:
        raise SystemExit('work item load anchor missing')
    text = text.replace(old, new, 1)

# Replace the work-item invalidation loop body tail to scope impacts and fail closed on evidence removal.
old = '''    if (item.status === "completed" || item.status === "failed" || item.status === "stale") {\n      await ctx.db.patch(item._id, {\n        status: "queued",\n        attemptCount: 0,\n        completedAt: undefined,\n        startedAt: undefined,\n        claimedAt: undefined,\n        leaseExpiresAt: undefined,\n        reservedCostUnits: undefined,\n        reservationDateKey: undefined,\n        actualCostUnits: undefined,\n        outputSummary: undefined,\n        blockedReason: undefined,\n        humanGateType: undefined,\n        lastError: reason,\n        updatedAt: input.now,\n      });\n    }\n  }\n\n  const findings = await ctx.db'''
new = '''    if (impactedKinds && !impactedKinds.has(item.kind)) continue;\n\n    if (input.action === "removed" && gateRootKind && item.kind === gateRootKind) {\n      const block = removedEvidenceGateBlock(input.evidenceKind);\n      if (block) {\n        await ctx.db.patch(item._id, {\n          status: "blocked",\n          attemptCount: 0,\n          completedAt: undefined,\n          startedAt: undefined,\n          claimedAt: undefined,\n          leaseExpiresAt: undefined,\n          reservedCostUnits: undefined,\n          reservationDateKey: undefined,\n          actualCostUnits: undefined,\n          outputSummary: undefined,\n          blockedReason: block.blockedReason,\n          humanGateType: block.humanGateType,\n          lastError: reason,\n          updatedAt: input.now,\n        });\n        await ctx.db.insert("atlasExecutionEvents", {\n          inventionId,\n          workItemId: item._id,\n          eventType: "work_blocked",\n          actorType: "system",\n          summary: block.summary,\n          metadata: { evidenceKind: input.evidenceKind, sourceId: input.sourceId ? String(input.sourceId) : undefined },\n          createdAt: input.now,\n        });\n        continue;\n      }\n    }\n\n    if (item.status === "completed" || item.status === "failed" || item.status === "stale") {\n      await ctx.db.patch(item._id, {\n        status: "queued",\n        attemptCount: 0,\n        completedAt: undefined,\n        startedAt: undefined,\n        claimedAt: undefined,\n        leaseExpiresAt: undefined,\n        reservedCostUnits: undefined,\n        reservationDateKey: undefined,\n        actualCostUnits: undefined,\n        outputSummary: undefined,\n        blockedReason: undefined,\n        humanGateType: undefined,\n        lastError: reason,\n        updatedAt: input.now,\n      });\n    }\n  }\n\n  const findings = await ctx.db'''
if new not in text:
    if old not in text:
        raise SystemExit('work invalidation anchor missing')
    text = text.replace(old, new, 1)

# Replace broad findings/deliverables invalidation with scoped behavior and preserve source links on upload.
old = '''  for (const finding of findings) {\n    const sourceIds = input.sourceId\n      ? finding.sourceIds.filter((sourceId) => sourceId !== input.sourceId)\n      : finding.sourceIds;\n    await ctx.db.patch(finding._id, {\n      sourceIds,\n      status: "stale",\n      updatedAt: input.now,\n    });\n  }\n\n  const deliverables = await ctx.db\n    .query("atlasDeliverables")\n    .withIndex("by_inventionId", (q) => q.eq("inventionId", inventionId))\n    .collect();\n\n  for (const deliverable of deliverables) {\n    const sourceIds = input.sourceId\n      ? deliverable.sourceIds.filter((sourceId) => sourceId !== input.sourceId)\n      : deliverable.sourceIds;\n    await ctx.db.patch(deliverable._id, {\n      sourceIds,\n      staleReason: reason,\n      updatedAt: input.now,\n    });\n  }'''
new = '''  const deliverables = await ctx.db\n    .query("atlasDeliverables")\n    .withIndex("by_inventionId", (q) => q.eq("inventionId", inventionId))\n    .collect();\n  const workKindById = new Map(workItems.map((item) => [String(item._id), item.kind]));\n  const impactedDeliverableIds = new Set<string>();\n\n  for (const deliverable of deliverables) {\n    const linkedKind = deliverable.workItemId ? workKindById.get(String(deliverable.workItemId)) : undefined;\n    const directlyReferencesRemovedSource = Boolean(\n      input.action === "removed" &&\n      input.sourceId &&\n      deliverable.sourceIds.some((sourceId) => sourceId === input.sourceId)\n    );\n    const graphImpacted = impactedKinds === null || Boolean(linkedKind && impactedKinds.has(linkedKind));\n    if (!graphImpacted && !directlyReferencesRemovedSource) continue;\n\n    const sourceIds = input.action === "removed" && input.sourceId\n      ? deliverable.sourceIds.filter((sourceId) => sourceId !== input.sourceId)\n      : deliverable.sourceIds;\n    await ctx.db.patch(deliverable._id, {\n      sourceIds,\n      staleReason: reason,\n      updatedAt: input.now,\n    });\n    impactedDeliverableIds.add(String(deliverable._id));\n  }\n\n  const deliverableDependencies = await ctx.db\n    .query("deliverableDependencies")\n    .withIndex("by_inventionId", (q) => q.eq("inventionId", inventionId))\n    .collect();\n  const impactedFindingIds = new Set(\n    deliverableDependencies\n      .filter((dependency) => dependency.dependencyType === "finding" && impactedDeliverableIds.has(String(dependency.deliverableId)))\n      .map((dependency) => dependency.dependencyId)\n  );\n\n  for (const finding of findings) {\n    const directlyReferencesRemovedSource = Boolean(\n      input.action === "removed" &&\n      input.sourceId &&\n      finding.sourceIds.some((sourceId) => sourceId === input.sourceId)\n    );\n    const shouldStale = impactedKinds === null || impactedFindingIds.has(String(finding._id)) || directlyReferencesRemovedSource;\n    if (!shouldStale) continue;\n\n    const sourceIds = input.action === "removed" && input.sourceId\n      ? finding.sourceIds.filter((sourceId) => sourceId !== input.sourceId)\n      : finding.sourceIds;\n    await ctx.db.patch(finding._id, {\n      sourceIds,\n      status: "stale",\n      updatedAt: input.now,\n    });\n  }'''
if new not in text:
    if old not in text:
        raise SystemExit('findings/deliverables anchor missing')
    text = text.replace(old, new, 1)

path.write_text(text, encoding='utf-8')

# Adjust existing behavioral expectation: known prototype evidence must not rerun unrelated market analysis.
test = Path('src/__tests__/evidence-impact-behavior.regression.test.ts')
t = test.read_text(encoding='utf-8')
t = t.replace('it("records extracted evidence, releases the matching real-world gate, and invalidates downstream outputs", async () => {', 'it("records extracted evidence, releases the matching real-world gate, and invalidates only its downstream outputs", async () => {')
t = t.replace('''    const downstream = tables.atlasWorkItems.find((item) => item._id === "work_market")!;\n    expect(downstream.status).toBe("queued");\n    expect(downstream.attemptCount).toBe(0);\n    expect(downstream.completedAt).toBeUndefined();\n    expect(downstream.outputSummary).toBeUndefined();\n    expect(downstream.lastError).toContain("Inventor evidence was uploaded");''', '''    const unrelatedMarket = tables.atlasWorkItems.find((item) => item._id === "work_market")!;\n    expect(unrelatedMarket.status).toBe("completed");\n    expect(unrelatedMarket.outputSummary).toBe("Old market analysis");''')
# Fake table must exist for the new query.
t = t.replace('''      atlasDeliverables: [{''', '''      deliverableDependencies: [],\n      atlasDeliverables: [{''', 1)
t = t.replace('''      atlasDeliverables: [],\n      atlasExecutionEvents: [],''', '''      atlasDeliverables: [],\n      deliverableDependencies: [],\n      atlasExecutionEvents: [],''')
test.write_text(t, encoding='utf-8')

# Extend real-world gate behavior with quote-specific downstream scope and removal fail-closed behavior.
test = Path('src/__tests__/real-world-evidence-gates.behavior.regression.test.ts')
t = test.read_text(encoding='utf-8')
t = t.replace('''    atlasDeliverables: [],\n    atlasExecutionEvents: [],''', '''    atlasDeliverables: [],\n    deliverableDependencies: [],\n    atlasExecutionEvents: [],''')
insert = '''\n  it("refreshes quote-dependent costing/readiness without rerunning unrelated completed work", async () => {\n    const { ctx, tables } = fakeContext(baseTables([\n      blockedGate("manufacturer_quote_evidence", "quote_gate"),\n      { _id: "costing", inventionId: "inv_1", kind: "manufacturing_unit_economics", status: "completed", attemptCount: 1, completedAt: 20, outputSummary: "Pre-quote cost model", updatedAt: 20 },\n      { _id: "comparison", inventionId: "inv_1", kind: "manufacturer_quote_comparison", status: "completed", attemptCount: 1, completedAt: 21, outputSummary: "Old comparison", dependsOnKinds: ["manufacturing_unit_economics", "manufacturer_quote_evidence"], updatedAt: 21 },\n      { _id: "readiness", inventionId: "inv_1", kind: "manufacturing_readiness", status: "completed", attemptCount: 1, completedAt: 22, outputSummary: "Old readiness", dependsOnKinds: ["manufacturer_quote_comparison"], updatedAt: 22 },\n      { _id: "market", inventionId: "inv_1", kind: "market_analysis", status: "completed", attemptCount: 1, completedAt: 10, outputSummary: "Unrelated market result", updatedAt: 10 },\n    ]));\n\n    await applyInventorEvidenceChange(ctx, "inv_1" as any, {\n      action: "uploaded",\n      sourceId: "quote_source_2" as any,\n      label: "Updated factory quote",\n      evidenceKind: "manufacturer_quote",\n      extraction: { supplier: "Example Factory", unitPrice: 4.25 },\n      now: 500,\n    });\n\n    expect(tables.atlasWorkItems.find((item) => item._id === "quote_gate")?.status).toBe("queued");\n    expect(tables.atlasWorkItems.find((item) => item._id === "costing")?.status).toBe("queued");\n    expect(tables.atlasWorkItems.find((item) => item._id === "comparison")?.status).toBe("queued");\n    expect(tables.atlasWorkItems.find((item) => item._id === "readiness")?.status).toBe("queued");\n    expect(tables.atlasWorkItems.find((item) => item._id === "market")?.status).toBe("completed");\n  });\n\n  it("blocks a previously satisfied quote gate when its real quote evidence is removed", async () => {\n    const { ctx, tables } = fakeContext(baseTables([\n      { _id: "quote_gate", inventionId: "inv_1", kind: "manufacturer_quote_evidence", status: "completed", attemptCount: 1, completedAt: 20, outputSummary: "Quote confirmed", updatedAt: 20 },\n      { _id: "comparison", inventionId: "inv_1", kind: "manufacturer_quote_comparison", status: "completed", attemptCount: 1, completedAt: 21, outputSummary: "Old comparison", dependsOnKinds: ["manufacturer_quote_evidence"], updatedAt: 21 },\n    ]));\n\n    await applyInventorEvidenceChange(ctx, "inv_1" as any, {\n      action: "removed",\n      sourceId: "quote_source" as any,\n      label: "Factory RFQ response",\n      evidenceKind: "manufacturer_quote",\n      now: 600,\n    });\n\n    const gate = tables.atlasWorkItems.find((item) => item._id === "quote_gate")!;\n    expect(gate.status).toBe("blocked");\n    expect(gate.humanGateType).toBe("authorization");\n    expect(gate.blockedReason).toMatch(/current real manufacturer quote/i);\n    expect(tables.atlasWorkItems.find((item) => item._id === "comparison")?.status).toBe("queued");\n    expect(tables.atlasExecutionEvents).toEqual(expect.arrayContaining([\n      expect.objectContaining({ eventType: "work_blocked", workItemId: "quote_gate" }),\n    ]));\n  });\n'''
marker = '\n  it("does not release an external gate for removed or mismatched evidence", async () => {'
if insert not in t:
    if marker not in t:
        raise SystemExit('behavior test insertion marker missing')
    t = t.replace(marker, insert + marker, 1)
test.write_text(t, encoding='utf-8')

# Unit-test the impact graph itself.
test = Path('src/__tests__/evidence-impact-scope.regression.test.ts')
test.write_text('''import { describe, expect, it } from "vitest";\nimport { impactedWorkKindsForEvidence } from "@convex/evidenceImpactScopeLogic";\n\nconst items = [\n  { kind: "manufacturer_quote_evidence", dependsOnKinds: ["manufacturer_rfq_package"] },\n  { kind: "manufacturing_unit_economics", dependsOnKinds: ["manufacturer_rfq_package"] },\n  { kind: "manufacturer_quote_comparison", dependsOnKinds: ["manufacturer_quote_evidence", "manufacturing_unit_economics"] },\n  { kind: "manufacturing_agreement_checklist", dependsOnKinds: ["manufacturer_quote_comparison"] },\n  { kind: "manufacturing_readiness", dependsOnKinds: ["manufacturer_quote_comparison", "manufacturing_agreement_checklist", "prototype_readiness"] },\n  { kind: "market_analysis", dependsOnKinds: ["validation_research"] },\n];\n\ndescribe("InventSmith scoped real-world evidence impact", () => {\n  it("refreshes quote-dependent costing and downstream manufacturing readiness only", () => {\n    const impacted = impactedWorkKindsForEvidence(items, "manufacturer_quote");\n    expect(impacted).not.toBeNull();\n    expect([...impacted!]).toEqual(expect.arrayContaining([\n      "manufacturer_quote_evidence",\n      "manufacturing_unit_economics",\n      "manufacturer_quote_comparison",\n      "manufacturing_agreement_checklist",\n      "manufacturing_readiness",\n    ]));\n    expect(impacted!.has("market_analysis")).toBe(false);\n  });\n\n  it("retains conservative broad invalidation for unclassified general evidence", () => {\n    expect(impactedWorkKindsForEvidence(items, "interview")).toBeNull();\n    expect(impactedWorkKindsForEvidence(items, undefined)).toBeNull();\n  });\n});\n''', encoding='utf-8')

print('Applied scoped evidence invalidation and regression coverage')
